'use strict';
window.JavaCollectionsTutorial=(()=>{
  const course=window.JAVA_DATA_STRUCTURES_TUTORIAL;
  const href=item=>'#/lesson/'+item.id+'?language=java&round=technical';
  const courseHref='#/learning?language=java';
  const items=()=>course.items.map(id=>baseData.find(item=>item.id===id)).filter(Boolean);
  const reviewed=item=>state.javaTutorialProgress?.[item.id]===item.tutorial.version;
  const ul=values=>`<ul>${values.map(value=>`<li>${esc(value)}</li>`).join('')}</ul>`;
  const code=value=>`<div class="codeblock"><pre><code>${esc(value)}</code></pre></div>`;
  function checkRecord(item){const record=state.javaTutorialChecks?.[item.id];return record?.version===item.tutorial.version&&Number.isInteger(record.choice)&&record.choice>=0&&record.choice<item.tutorial.check.options.length?record:null;}
  function progress(all){const done=all.filter(reviewed).length;return `<div class="tutorial-progress"><div><strong>${done} of ${all.length} lessons reviewed</strong><span>Reviewed by you</span></div><progress value="${done}" max="${all.length}" aria-label="Tutorial lessons reviewed">${done} of ${all.length}</progress><p>Quick checks help you practise. Reviews record your own assessment.</p></div>`;}
  function navigation(all,current){
    const links=all.map((item,index)=>`${index===0||all[index-1].tutorial.group!==item.tutorial.group?`<span class="tutorial-nav-group">${esc(item.tutorial.group)}</span>`:''}<a href="${href(item)}" ${item.id===current?'aria-current="step"':''}><span class="tutorial-nav-marker ${reviewed(item)?'is-reviewed':''}" aria-hidden="true">${reviewed(item)?'✓':index+1}</span><span><strong>${esc(item.tutorial.title)}</strong><small>${reviewed(item)?'Reviewed':`About ${item.tutorial.minutes} min`}</small></span></a>`).join('');
    return `<aside class="tutorial-sidebar"><a class="tutorial-course-label" href="${courseHref}">Java data-structures tutorial</a>${progress(all)}<nav class="tutorial-desktop-lessons" aria-label="Tutorial lessons">${links}</nav><details class="tutorial-mobile-contents"><summary>Browse ${all.length} lessons</summary><nav aria-label="Tutorial lessons">${links}</nav></details><p class="tutorial-sidebar-note">Follow the sequence or revisit any lesson. JDK types and custom implementations are clearly labelled.</p></aside>`;
  }
  function overview(){
    if((route().path==='learning'||route().path==='concepts'?state.conceptLanguage:currentLanguage)!=='java')return `<div class="empty"><h1>Java data-structures tutorial</h1><p>This tutorial is available in Java 17. Python, JavaScript and TypeScript practice remain in Practice. Open the Java edition to learn these structures.</p><a class="button primary" href="${courseHref}">Open Java tutorial</a></div>`;
    const all=items(),next=all.find(item=>!reviewed(item))||all[0],done=all.filter(reviewed).length,minutes=all.reduce((sum,item)=>sum+item.tutorial.minutes,0);
    return `<div class="java-tutorial tutorial-overview"><header class="tutorial-hero"><div><span class="tutorial-eyebrow">GUIDED TUTORIAL · JAVA 17</span><h1>${esc(course.title)}</h1><p>From arrays and collections to heaps, trees, graphs and range queries. Learn the structure, trace a verified example, check your understanding and practise explaining the trade-offs.</p><div class="tutorial-course-meta"><span>${all.length} lessons</span><span>About ${Math.round(minutes/60)} hours, at your pace</span><span>JDK & algorithm references</span></div><a class="button primary large" href="${href(next)}">${done===all.length?'Revisit the tutorial':done?'Continue learning':'Start the tutorial'}</a></div><div class="tutorial-course-progress">${progress(all)}<strong>Learn. Trace. Check. Explain.</strong><p>Small lessons build from collection basics to diagnosing real performance problems.</p></div></header><section class="tutorial-how" aria-label="How each lesson works"><article><strong>Understand the idea</strong><p>Read a plain-language explanation and compare the operations that matter.</p></article><article><strong>Follow the example</strong><p>Predict the output before revealing the result and its explanation.</p></article><article><strong>Make it your own</strong><p>Check your understanding, then rehearse an interview answer in your own words.</p></article></section><section class="tutorial-coverage"><span class="tutorial-eyebrow">EXPLORE THE STRUCTURES</span><h2>A place for every core family.</h2><div>${course.sections.map(section=>{const first=all.find(item=>item.id===section.ids[0]);return `<a href="${href(first)}"><strong>${esc(section.title)}</strong><span>${section.ids.length} lessons</span><p>${esc({Foundations:'Arrays, character sequences, collection contracts and safe copies.','Linear structures':'ArrayList, LinkedList, stacks, deques, queues and priority heaps.',Sets:'HashSet, LinkedHashSet, TreeSet, EnumSet and BitSet.',Maps:'HashMap, TreeMap, map interfaces, identity, order and specialized maps.','Concurrent structures':'Concurrent maps and sets, copy-on-write and blocking queues.','Custom structures':'Binary trees, graphs, tries, disjoint sets, Fenwick and segment trees.'}[section.title])}</p></a>`;}).join('')}</div></section><section class="tutorial-syllabus"><div><span class="tutorial-eyebrow">YOUR LEARNING SEQUENCE</span><h2>One useful idea at a time.</h2><p>Basic Java syntax is helpful. You can start without prior collections experience.</p></div><ol>${all.map(item=>`<li><a href="${href(item)}"><div><span>${esc(item.tutorial.group)} · lesson ${item.tutorial.index+1} · about ${item.tutorial.minutes} min</span><h3>${esc(item.tutorial.title)}</h3><p>${esc(item.tutorial.lead)}</p></div><strong>${reviewed(item)?'✓ Reviewed':'Open lesson'}</strong></a></li>`).join('')}</ol></section><p class="tutorial-footnote">Tutorial progress is saved in this browser for the current workspace. It is a study record, not an interview readiness score. Time estimates are a planning guide.</p></div>`;
  }
  function quiz(item){const t=item.tutorial,q=t.check,record=checkRecord(item),correct=record?.choice===q.correct;return `<section class="tutorial-check tutorial-panel" aria-labelledby="tutorial-check-heading"><span class="tutorial-eyebrow">PAUSE AND CHECK</span><h2 id="tutorial-check-heading">Can you apply the idea?</h2><form data-tutorial-quiz="${item.id}"><fieldset><legend>${esc(q.question)}</legend>${q.options.map((option,index)=>`<label><input type="radio" name="choice" value="${index}" ${record?.choice===index?'checked':''} required><span>${esc(option)}</span></label>`).join('')}</fieldset><button class="button primary" type="submit">${record?'Check again':'Check my answer'}</button></form>${record?`<div class="tutorial-feedback" id="tutorial-check-feedback" role="status" tabindex="-1" data-correct="${correct}"><strong>${correct?'That’s right.':'Let’s look at the reasoning.'}</strong><p>${esc(q.explanation)}</p><button class="tutorial-text-button" data-tutorial-retry="${item.id}">Try the check again</button></div>`:'<p class="tutorial-check-note">Choose an answer to see the reasoning. This is a learning check, not a graded assessment.</p>'}</section>`;}
  function lesson(item){
    const all=items(),t=item.tutorial,index=all.findIndex(other=>other.id===item.id),done=reviewed(item),draft=state.drafts[item.id]||'',sources=item.sources;
    return `<div class="java-tutorial tutorial-lesson"><a class="tutorial-back" href="${courseHref}">Back to tutorial overview</a><div class="tutorial-layout">${navigation(all,item.id)}<div class="tutorial-main"><header class="tutorial-lesson-heading"><span class="tutorial-eyebrow">JAVA 17 · LESSON ${index+1} OF ${all.length} · ABOUT ${t.minutes} MIN</span><h1>${esc(t.title)}</h1><p>${esc(t.lead)}</p><span class="tutorial-origin">${esc(t.origin)}</span>${t.origin==='Custom implementation'?'<p class="tutorial-origin-note">Build this structure yourself using Java types. It is not a general-purpose collection supplied by Java 17.</p>':''}<button class="tutorial-question-link" data-tutorial-jump>Practise the interview question</button></header><section class="tutorial-goals"><h2>By the end of this lesson</h2>${ul(t.goals)}</section><section class="tutorial-panel tutorial-explanation"><span class="tutorial-eyebrow">UNDERSTAND</span><h2>The idea, in practice</h2><p class="tutorial-takeaway">${esc(t.summary)}</p>${t.explanation}</section><section class="tutorial-panel tutorial-example"><span class="tutorial-eyebrow">TRACE THE EXAMPLE</span><h2>See what the code does</h2><p>${esc(t.scenario)}</p><div class="tutorial-input"><strong>Input / setup</strong><p>${esc(item.example.input)}</p></div><p>Read the code from top to bottom. Predict what each print statement will produce.</p>${code(item.example.code)}<details class="tutorial-output"><summary>Show output and explanation</summary><div><strong>Expected output</strong>${code(item.example.output)}<h3>Why this happens</h3><p>${esc(t.why)}</p></div></details><p class="tutorial-example-note">Runnable Java 17 code. The output above is a verified teaching example; this page does not execute code.</p></section>${quiz(item)}<section class="tutorial-panel tutorial-pitfalls"><span class="tutorial-eyebrow">BUILD GOOD HABITS</span><h2>Watch for these mistakes</h2>${ul(t.pitfalls)}</section><section class="tutorial-panel tutorial-interview" id="tutorial-interview" tabindex="-1"><span class="tutorial-eyebrow">EXPLAIN IT YOURSELF</span><h2>Bring it into the interview</h2><p>${esc(t.prompt)}</p><label for="code-draft">Your answer in your own words</label><textarea id="code-draft" rows="5" placeholder="State the idea, name the operation and explain one example…">${esc(draft)}</textarea><small>Saved automatically in this browser. Your previous answer draft is preserved.</small><details class="answer"><summary>Show a sample interview answer</summary><div class="answer-content"><p>${esc(t.summary)}</p><p>${esc(t.why)}</p></div></details><h3>Keep the conversation going</h3>${ul(t.followups)}</section><section class="tutorial-references tutorial-panel"><h2>References and further reading</h2><ul>${sources.map(source=>`<li><a href="${source.url}" target="_blank" rel="noopener noreferrer">${esc(source.title)}</a></li>`).join('')}</ul><p>References reviewed ${esc(item.reviewedAt)} · Java 17 baseline. Examples describe behaviour; complexity is not a measured latency guarantee.</p></section><section class="tutorial-lesson-end"><div><h2>${done?'Lesson reviewed':'Ready for the next idea?'}</h2><p>Try explaining the idea without looking. Mark it reviewed when you are comfortable, or come back for another pass.</p></div><button class="button ${done?'':'primary'}" data-tutorial-review="${item.id}" aria-pressed="${done}">${done?'Reopen lesson':'Mark lesson reviewed'}</button></section><nav class="tutorial-pagination" aria-label="Previous and next tutorial lesson">${index?`<a class="button" href="${href(all[index-1])}">Previous lesson</a>`:'<span></span>'}${index<all.length-1?`<a class="button primary" href="${href(all[index+1])}">Next: ${esc(all[index+1].tutorial.title)}</a>`:`<a class="button primary" href="${courseHref}">Review the tutorial</a>`}</nav></div></div></div>`;
  }
  function entry(){return (isConceptRoute()?state.conceptLanguage:currentLanguage)==='java'?`<section class="tutorial-entry"><div><span class="tutorial-eyebrow">LEARN BEFORE YOU REHEARSE</span><h2>A guided Java data-structures tutorial</h2><p>Follow ${course.items.length} lessons with explanations, examples and quick checks, from arrays to custom trees and graphs.</p></div><a class="button primary" href="${courseHref}">Open tutorial</a></section>`:`<div class="domain-note">Learn currently provides a Java 17 data-structures tutorial. <a href="${courseHref}">Open the Java tutorial</a>, or use Practice for other coding languages.</div>`;}
  function available(){return window.PrepPilotUI.workspaceReady?.()===true;}
  function find(id){return items().find(item=>item.id===id);}
  document.addEventListener('submit',event=>{
    const id=event.target.dataset.tutorialQuiz;if(!id)return;event.preventDefault();
    const item=find(id);if(!item||!available()){toast('Your workspace is loading. Try again in a moment.');return;}
    const value=new FormData(event.target).get('choice'),choice=value===null?NaN:Number(value);
    if(!Number.isInteger(choice)||choice<0||choice>=item.tutorial.check.options.length)return;
    state.javaTutorialChecks??={};state.javaTutorialChecks[id]={version:item.tutorial.version,choice};persist();render();
    document.getElementById('tutorial-check-feedback')?.focus({preventScroll:true});
  });
  document.addEventListener('click',event=>{
    if(event.target.closest('[data-tutorial-jump]')){const section=document.getElementById('tutorial-interview');section?.scrollIntoView({block:'start'});section?.focus({preventScroll:true});return;}
    const review=event.target.closest('[data-tutorial-review]'),retry=event.target.closest('[data-tutorial-retry]');
    if(!review&&!retry)return;
    if(!available()){toast('Your workspace is loading. Try again in a moment.');return;}
    if(review){const item=find(review.dataset.tutorialReview);if(!item)return;state.javaTutorialProgress??={};if(reviewed(item))delete state.javaTutorialProgress[item.id];else state.javaTutorialProgress[item.id]=item.tutorial.version;persist();render();document.querySelector('[data-tutorial-review]')?.focus({preventScroll:true});}
    if(retry){delete state.javaTutorialChecks?.[retry.dataset.tutorialRetry];persist();render();document.querySelector('[data-tutorial-quiz] input')?.focus({preventScroll:true});}
  });
  return {overview,lesson,entry,checkRecord};
})();
